# owner: platform
import unittest

from hourglass.rounding import span_labels
from hourglass.models import Span

class RoundingTests(unittest.TestCase):
    def test_already_on_step(self):
        labels = span_labels([Span(540, 1035)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_snaps_to_nearest(self):
        labels = span_labels([Span(543, 1030)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = span_labels([Span(555, 600)], 30)
        self.assertEqual(labels, ["09:30-10:00 (0h 30m)"])

    def test_order_and_count_kept(self):
        spans = [Span(600, 660), Span(60, 120)]
        labels = span_labels(spans, 30)
        self.assertEqual(len(labels), 2)
        self.assertTrue(labels[0].startswith("10:00"))

    def test_empty_list(self):
        self.assertEqual(span_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120, 2.5):
            with self.assertRaises(ValueError):
                span_labels([Span(0, 60)], step)

    def test_span_collapsing_raises(self):
        with self.assertRaises(ValueError):
            span_labels([Span(601, 603)], 15)

if __name__ == "__main__":
    unittest.main()
